refentry.refsect1:
  &reftitle.examples;

   सक्रिय connection बाट stream खोल्ने तरिका


<?php
$session = ssh2_connect('example.com', 22);
ssh2_auth_pubkey_file($session, 'username', '/home/username/.ssh/id_rsa.pub',
                                            '/home/username/.ssh/id_rsa', 'secret');
$stream = fopen("ssh2.tunnel://$session/remote.example.com:1234", 'r');
?>




   यो $session variable उपलब्ध रहिरहनु पर्छ!

    ssh2.*://$session wrappers प्रयोग गर्नका लागि
    $session resource variable लाई कायम राख्नुपर्छ।
    तलको code ले अपेक्षित नतिजा दिने छैन:



<?php
$session = ssh2_connect('example.com', 22);
ssh2_auth_pubkey_file($session, 'username', '/home/username/.ssh/id_rsa.pub',
                                            '/home/username/.ssh/id_rsa', 'secret');
$connection_string = "ssh2.sftp://$session/";
unset($session);
$stream = fopen($connection_string . "path/to/file", 'r');
?>



    unset() ले session बन्द गर्छ, किनकि $connection_string ले
    $session variable को reference राख्दैन, त्यसबाट बनेको
    string cast मात्र राख्छ। कुनै scope (जस्तै function) बाट बाहिरिँदा
    unset स्वतः (implicit रूपमा) हुँदा पनि यस्तै हुन्छ।
